create table if not exists app.transaction_events(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references app.transactions(id) on delete cascade,actor_person_id uuid references app.persons(id) on delete set null,event_type text not null,from_status text,to_status text,note text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists app.transaction_disputes(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references app.transactions(id) on delete cascade,opened_by_person_id uuid not null references app.persons(id),reason text not null,details text,status text not null default 'open' check(status in ('open','under_review','resolved_buyer','resolved_seller','resolved_mutual','dismissed','cancelled')),resolution text,resolved_by_person_id uuid references app.persons(id),opened_at timestamptz not null default now(),resolved_at timestamptz,updated_at timestamptz not null default now());
create table if not exists app.transaction_refunds(id uuid primary key default gen_random_uuid(),transaction_id uuid not null references app.transactions(id) on delete cascade,requested_by_person_id uuid not null references app.persons(id),amount numeric(14,2) not null check(amount>0),currency varchar(3) not null,status text not null default 'requested' check(status in ('requested','approved','declined','sent','confirmed','cancelled')),reason text,external_reference text,approved_by_person_id uuid references app.persons(id),sent_at timestamptz,confirmed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists app.election_result_snapshots(id uuid primary key default gen_random_uuid(),election_id uuid not null references app.elections(id) on delete cascade,snapshot_type text not null default 'count' check(snapshot_type in ('count','recount','certified')),total_ballots int not null default 0,total_receipts int not null default 0,turnout_percent numeric(7,4),quorum_met boolean,result_data jsonb not null default '{}'::jsonb,computed_by_person_id uuid references app.persons(id),created_at timestamptz not null default now());
create table if not exists app.election_certifications(id uuid primary key default gen_random_uuid(),election_id uuid not null references app.elections(id) on delete cascade,result_snapshot_id uuid references app.election_result_snapshots(id) on delete restrict,certified_by_person_id uuid not null references app.persons(id),certification_note text,evidence jsonb not null default '{}'::jsonb,certified_at timestamptz not null default now(),revoked_at timestamptz,revoked_by_person_id uuid references app.persons(id),revocation_reason text);
create table if not exists app.election_recounts(id uuid primary key default gen_random_uuid(),election_id uuid not null references app.elections(id) on delete cascade,requested_by_person_id uuid not null references app.persons(id),reason text not null,status text not null default 'requested' check(status in ('requested','approved','running','completed','declined','cancelled')),completed_snapshot_id uuid references app.election_result_snapshots(id),reviewed_by_person_id uuid references app.persons(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into app.permissions(key,domain,action,description,is_sensitive) values ('transactions.dispute','transactions','dispute','Open and manage own transaction disputes',false),('transactions.resolve_dispute','transactions','resolve_dispute','Resolve transaction disputes',true),('transactions.refund','transactions','refund','Approve and record transaction refunds',true),('governance.certify','governance','certify','Compute and certify election results',true),('governance.recount','governance','recount','Approve and record election recounts',true) on conflict(key) do nothing;
insert into app.role_permissions(role_id,permission_id) select r.id,p.id from app.roles r join app.permissions p on p.key in ('transactions.resolve_dispute','transactions.refund','governance.certify','governance.recount') where r.key='administrator' on conflict do nothing;
insert into app.role_permissions(role_id,permission_id) select r.id,p.id from app.roles r join app.permissions p on p.key='transactions.dispute' where r.key in ('member','family_member') on conflict do nothing;
insert into app.role_permissions(role_id,permission_id) select r.id,p.id from app.roles r join app.permissions p on p.key in ('governance.certify','governance.recount') where r.key in ('president','governing_board') on conflict do nothing;
